package contract

import (
	"path/filepath"
	"slices"
	"strings"
	"unicode"
)

var Languages = []Language{PHP, Vue, TypeScript, Python, CSharp, Go}

// facts is what the tool knows of a language besides parsing it, stated once for every package that needs it: its
// file extensions, the name a reader sees, how a line comment is written and opened, and how a generated file is told.
type facts struct {
	extensions        []string
	label             string
	comment           [2]string
	commentOpeners    []string
	generatedNames    []string
	generatedHeadings []string
	openings          []string
	// testNames are the file names the language's test tools run by default, as patterns on a file's base name.
	testNames []string
	// holds is the languages a stream of this one carries files of too: a Vue stream holds the TypeScript its
	// components import.
	holds []Language
	// namespaceSeparator splits a qualified name into its namespaces: `\` in PHP, `.` in C# and Python.
	namespaceSeparator string
	// namesIgnoreCase is whether the language reads a qualified name the same in any case, as PHP does.
	namesIgnoreCase                                    bool
	memberVisibility, typeVisibility, visibilityByName string
	exportedBy                                         string
	lexicon                                            Lexicon
	removedWith                                        []string
}

var described = map[Language]facts{
	PHP:        {extensions: []string{"php"}, label: "PHP", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}, openings: []string{"<?php"}, namespaceSeparator: `\`, namesIgnoreCase: true, memberVisibility: "public", typeVisibility: "public", removedWith: []string{"unset"}, lexicon: Lexicon{LineComments: []string{"//", "#"}, NotComments: []string{"#["}, BlockComment: [2]string{"/*", "*/"}, Quotes: []Quote{{Open: "<<<", Heredoc: true}, {Open: "'", Close: "'", Escapes: true}, {Open: `"`, Close: `"`, Escapes: true}}}},
	Vue:        {extensions: []string{"vue"}, label: "Vue", comment: [2]string{"<!-- ", " -->"}, commentOpeners: []string{"<!--"}, holds: []Language{TypeScript}, memberVisibility: "public", typeVisibility: "public", exportedBy: "export", lexicon: Lexicon{BlockComment: [2]string{"<!--", "-->"}, Regions: []Region{{Open: "<script", Close: "</script>", Language: TypeScript}}}},
	TypeScript: {extensions: []string{"ts", "tsx", "mts", "cts", "js", "jsx", "mjs", "cjs"}, label: "TypeScript", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}, testNames: []string{"*.test.*", "*.spec.*"}, memberVisibility: "public", typeVisibility: "public", exportedBy: "export", lexicon: Lexicon{LineComments: []string{"//"}, BlockComment: [2]string{"/*", "*/"}, Quotes: []Quote{{Open: "`", Close: "`", Escapes: true, Code: [2]string{"${", "}"}}, {Open: "'", Close: "'", Escapes: true}, {Open: `"`, Close: `"`, Escapes: true}}}},
	Python:     {extensions: []string{"py"}, label: "Python", comment: [2]string{"# ", ""}, commentOpeners: []string{"#"}, testNames: []string{"test_*.py", "*_test.py", "conftest.py"}, namespaceSeparator: ".", visibilityByName: "underscored", lexicon: Lexicon{LineComments: []string{"#"}, Quotes: []Quote{{Open: `"""`, Close: `"""`, Escapes: true}, {Open: "'''", Close: "'''", Escapes: true}, {Open: `"`, Close: `"`, Escapes: true}, {Open: "'", Close: "'", Escapes: true}}}},
	CSharp: {extensions: []string{"cs"}, label: "C#", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}, namespaceSeparator: ".",
		generatedNames: []string{".g.cs", ".g.i.cs", ".designer.cs", ".generated.cs"}, generatedHeadings: []string{"<auto-generated", "<autogenerated"}, memberVisibility: "private", typeVisibility: "internal", lexicon: Lexicon{LineComments: []string{"//"}, BlockComment: [2]string{"/*", "*/"}, Quotes: []Quote{{Open: `"""`, Close: `"""`}, {Open: `@"`, Close: `"`}, {Open: `@$"`, Close: `"`}, {Open: `"`, Close: `"`, Escapes: true}, {Open: "'", Close: "'", Escapes: true}}}},
	Go: {extensions: []string{"go"}, label: "Go", comment: [2]string{"// ", ""}, commentOpeners: []string{"//", "/*", "*"}, testNames: []string{"*_test.go"}, visibilityByName: "capitalised", lexicon: Lexicon{LineComments: []string{"//"}, BlockComment: [2]string{"/*", "*/"}, Quotes: []Quote{{Open: "`", Close: "`"}, {Open: `"`, Close: `"`, Escapes: true}, {Open: "'", Close: "'", Escapes: true}}}},
}

// OpensFirst says whether the file's first line must stay first: a #! line in any language, or the language's own
// opening, like PHP's <?php, so anything written at the top goes below it.
func OpensFirst(language Language, contents string) bool {
	return strings.HasPrefix(contents, "#!") || slices.ContainsFunc(described[language].openings, func(opening string) bool { return strings.HasPrefix(contents, opening) })
}

// Label is the language's name as a reader sees it.
func RemovesWith(language Language, keyword string) bool {
	return slices.Contains(described[language].removedWith, keyword)
}

func Label(language Language) string {
	return described[language].label
}

// CommentOf is the text written as a line comment of the language.
func CommentOf(language Language, text string) string {
	return described[language].comment[0] + text + described[language].comment[1]
}

// IsCommentLine says whether the line opens with a comment of the language.
func IsCommentLine(language Language, line string) bool {
	opened := strings.TrimLeft(line, " \t\n\r\x00\x0B")

	return slices.ContainsFunc(described[language].commentOpeners, func(opener string) bool { return strings.HasPrefix(opened, opener) })
}

// IsGenerated says whether a file of the language is one a tool wrote: by its name, or by what its opening comments say.
func IsGenerated(language Language, path, heading string) bool {
	name, heading := strings.ToLower(filepath.Base(path)), strings.ToLower(heading)

	return slices.ContainsFunc(described[language].generatedNames, func(suffix string) bool { return strings.HasSuffix(name, suffix) }) ||
		slices.ContainsFunc(described[language].generatedHeadings, func(mark string) bool { return strings.Contains(heading, mark) })
}

// IsTestName says whether the file's name is one the language's test tools run by default.
func IsTestName(language Language, path string) bool {
	name := filepath.Base(filepath.ToSlash(path))

	return slices.ContainsFunc(described[language].testNames, func(pattern string) bool {
		matched, _ := filepath.Match(pattern, name)

		return matched
	})
}

func ExtensionsOf(language Language) []string {
	return described[language].extensions
}

func LanguageOfPath(path string) (Language, bool) {
	extension := strings.ToLower(strings.TrimPrefix(filepath.Ext(path), "."))
	for _, language := range Languages {
		if slices.Contains(described[language].extensions, extension) {
			return language, true
		}
	}

	return "", false
}

// StreamLanguage is the language a stream of files in these languages is named for: the one that holds every other,
// as a bridge names a stream of Vue components and the TypeScript they import Vue, else the first.
func StreamLanguage(languages []Language) Language {
	for _, candidate := range languages {
		if !slices.ContainsFunc(languages, func(other Language) bool {
			return other != candidate && !slices.Contains(described[candidate].holds, other)
		}) {
			return candidate
		}
	}
	if len(languages) == 0 {
		return ""
	}

	return languages[0]
}

// NamespaceSeparator is what splits a qualified name of the language into its namespaces; none where it has none.
func NamespaceSeparator(language Language) string {
	return described[language].namespaceSeparator
}

// QualifiedNameKey is a qualified name as the language compares it: without a leading separator, and in one case
// where the language ignores case.
func QualifiedNameKey(language Language, name string) string {
	read := described[language]
	if read.namespaceSeparator != "" {
		name = strings.TrimLeft(name, read.namespaceSeparator)
	}
	if read.namesIgnoreCase {
		return strings.ToLower(name)
	}

	return name
}

func DefaultVisibility(language Language, name string, member bool, modifiers []string) string {
	held := described[language]
	if held.exportedBy != "" && !member {
		if slices.Contains(modifiers, held.exportedBy) {
			return "public"
		}

		return "private"
	}
	switch held.visibilityByName {
	case "capitalised":
		if first := []rune(name + " ")[0]; unicode.IsUpper(first) {
			return "public"
		}

		return "package"
	case "underscored":
		if strings.HasPrefix(name, "_") && !strings.HasSuffix(name, "__") {
			return "private"
		}

		return "public"
	}
	if member {
		return held.memberVisibility
	}

	return held.typeVisibility
}
